#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

const long long INF = 1e18;

struct Edge {
    int to;
    int weight;
};

int E, R;
vector<vector<Edge>> adj;
vector<int> visited;
vector<int> parent_node;
vector<int> parent_weight;
vector<int> depth;
vector<long long> cycle_len;

void find_cycles(int u, int p, int d) {
    visited[u] = 1;
    depth[u] = d;

    for (const auto& edge : adj[u]) {
        int v = edge.to;
        int w = edge.weight;

        if (v == p) continue;

        if (visited[v] == 1) {
            // Back-edge encontrada, ciclo detectado
            if (depth[v] < depth[u]) {
                long long current_cycle_len = w;
                vector<int> cycle_vertices;
                cycle_vertices.push_back(u);

                int curr = u;
                while (curr != v) {
                    current_cycle_len += parent_weight[curr];
                    curr = parent_node[curr];
                    cycle_vertices.push_back(curr);
                }

                for (int node : cycle_vertices) {
                    cycle_len[node] = current_cycle_len;
                }
            }
        } else if (visited[v] == 0) {
            parent_node[v] = u;
            parent_weight[v] = w;
            find_cycles(v, u, d + 1);
        }
    }

    visited[u] = 2;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> E >> R)) return 0;

    adj.resize(E + 1);
    for (int i = 0; i < R; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    visited.assign(E + 1, 0);
    parent_node.assign(E + 1, 0);
    parent_weight.assign(E + 1, 0);
    depth.assign(E + 1, 0);
    cycle_len.assign(E + 1, 0);

    for (int i = 1; i <= E; ++i) {
        if (!visited[i]) {
            find_cycles(i, 0, 1);
        }
    }

    int K;
    if (!(cin >> K)) return 0;

    vector<long long> dist(E + 1);

    while (K--) {
        int X;
        long long T;
        cin >> X >> T;

        fill(dist.begin(), dist.end(), INF);
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

        dist[X] = 0;
        pq.push({0, X});

        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();

            if (d > dist[u]) continue;

            for (const auto& edge : adj[u]) {
                int v = edge.to;
                long long w = edge.weight;
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }

        long long ans = INF;
        for (int i = 1; i <= E; ++i) {
            if (dist[i] != INF && cycle_len[i] >= T) {
                ans = min(ans, 2 * dist[i] + cycle_len[i]);
            }
        }

        if (ans == INF) {
            cout << -1 << "\n";
        } else {
            cout << ans << "\n";
        }
    }

    return 0;
}
